package LoopingStatements;

public class WhileLoop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
        int i=1;
        while(i<=10) {
        	System.out.println(i);
        	i++;
        }
        
        int j=10;
        System.out.println("reverse order");
        while(j>=1) {
        	System.out.println(j);
        	j--;
        }
	}

}
